236		}
237		if !strings.Contains(content, "entire search --json --compact") {
238			t.Fatal("scaffolded file should recommend `--json --compact` for scanning results")
239		}
240		if !strings.Contains(content, "entire checkpoint explain <id>") {
241			t.Fatal("scaffolded file should point drill-down at `entire checkpoint explain <id>`")
242		}
243		if !strings.Contains(content, "entire checkpoint explain --session <id>") {
244			t.Fatal("scaffolded file should bridge session hits via `explain --session`")
