249		if !strings.Contains(content, "session hits are projections of the same checkpoints") {
250			t.Fatal("scaffolded file should frame session hits as projections of checkpoints")
251		}
252		if !strings.Contains(content, "add `--full` to pull the checkpoint's entire session transcript") {
253			t.Fatal("scaffolded file should escalate to `explain --full` for the session transcript")
254		}
255		if !strings.Contains(content, "summarize from the compact fields alone") {
256			t.Fatal("scaffolded file should tell agents repo/pr and cross-repo hits aren't explainable")
